CREATE TABLE release_policies(project TEXT PRIMARY KEY NOT NULL REFERENCES projects(id), revision INTEGER NOT NULL CHECK(revision>0), policy TEXT NOT NULL CHECK(json_valid(policy)), updated INTEGER NOT NULL);
CREATE TABLE release_metadata(project TEXT NOT NULL REFERENCES projects(id), release TEXT NOT NULL, first_seen INTEGER NOT NULL, environment TEXT NOT NULL, sdk TEXT NOT NULL, auto_created INTEGER NOT NULL CHECK(auto_created IN (0,1)), version_key TEXT, PRIMARY KEY(project,release));
CREATE TABLE release_builds(project TEXT NOT NULL REFERENCES projects(id), release TEXT NOT NULL, build TEXT NOT NULL, registered INTEGER NOT NULL CHECK(registered IN (0,1)), PRIMARY KEY(project,release,build));
CREATE TABLE issue_resolutions(project TEXT NOT NULL REFERENCES projects(id), issue TEXT NOT NULL REFERENCES issues(id), mode TEXT NOT NULL CHECK(mode IN ('plain','current')), seen_without_release INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL, boundary_seq INTEGER, observed_seq INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(project,issue));
CREATE TRIGGER portability_release_policies_insert BEFORE INSERT ON release_policies WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_release_policies_update BEFORE UPDATE ON release_policies WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_release_policies_delete BEFORE DELETE ON release_policies WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_release_metadata_insert BEFORE INSERT ON release_metadata WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_release_metadata_update BEFORE UPDATE ON release_metadata WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
CREATE TRIGGER portability_release_metadata_delete BEFORE DELETE ON release_metadata WHEN EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL) BEGIN SELECT RAISE(ABORT,'restore_in_progress'); END;
